"use strict";(self.webpackChunkdocs_scadys_io=self.webpackChunkdocs_scadys_io||[]).push([["1547"],{6974(e){e.exports=JSON.parse('{"version":{"pluginId":"design","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"designSidebar":[{"type":"link","href":"/design/","label":"Overview","docId":"index","unlisted":false},{"type":"category","label":"Foundations","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/design/foundations/legibility","label":"Legibility","docId":"foundations/legibility","unlisted":false},{"type":"link","href":"/design/foundations/colour","label":"Colour","docId":"foundations/colour","unlisted":false},{"type":"link","href":"/design/foundations/typography","label":"Typography","docId":"foundations/typography","unlisted":false},{"type":"link","href":"/design/foundations/layout","label":"Layout","docId":"foundations/layout","unlisted":false},{"type":"link","href":"/design/foundations/materials-and-depth","label":"Materials and depth","docId":"foundations/materials-and-depth","unlisted":false},{"type":"link","href":"/design/foundations/motion","label":"Motion","docId":"foundations/motion","unlisted":false},{"type":"link","href":"/design/foundations/night","label":"Night","docId":"foundations/night","unlisted":false},{"type":"link","href":"/design/foundations/touch-accessibility","label":"Touch accessibility","docId":"foundations/touch-accessibility","unlisted":false}],"href":"/design/foundations/"}]},"docs":{"foundations/colour":{"id":"foundations/colour","title":"Colour","description":"Every colour on an MDD page is a named role, such as data, label or port, with one value for day and one for night. Pages, artwork and firmware refer to the role and never to a raw colour, so the whole display changes between day and night by changing the role values alone.","sidebar":"designSidebar"},"foundations/index":{"id":"foundations/index","title":"Foundations","description":"The Foundations are the rules every page follows before it shows any particular data. They set how a page is read, how it is coloured and lit, where things may sit and how it answers a touch.","sidebar":"designSidebar"},"foundations/layout":{"id":"foundations/layout","title":"Layout","description":"Every MDD page is designed once, on a square canvas of 720 \xd7 720 pixels, and each product shows that design on its own panel. Most data pages are built from two standard layouts, while the dial pages have their own.","sidebar":"designSidebar"},"foundations/legibility":{"id":"foundations/legibility","title":"Legibility","description":"An MDD display is an instrument, not a chart plotter. It shows the same page for days, usually with nobody touching it, and it is read in a glance from a helm or a bunk. Every other rule in these guidelines serves that glance.","sidebar":"designSidebar"},"foundations/materials-and-depth":{"id":"foundations/materials-and-depth","title":"Materials and depth","description":"The MIPI panels show 24-bit colour with transparency and smooth edges, so an MDD page can look built rather than printed. A dial sits recessed in its panel, a needle floats over the card and a readout window floats over the needle. Depth is used where it helps the eye find the data, and it gives way wherever it competes with the data.","sidebar":"designSidebar"},"foundations/motion":{"id":"foundations/motion","title":"Motion","description":"Movement on an MDD page carries meaning. A needle moves because the wind moved, and an alert throbs because something needs attention. Anything else that moves is noise, so a page keeps still everything that has no reason to move.","sidebar":"designSidebar"},"foundations/night":{"id":"foundations/night","title":"Night","description":"At night the display must be readable without spoiling the dark adaptation of the person reading it, or of anyone else on deck. The night palette is amber data on black, the brightness comes from the backlight rather than from the colours, and nothing on a night page is white.","sidebar":"designSidebar"},"foundations/touch-accessibility":{"id":"foundations/touch-accessibility","title":"Touch accessibility","description":"The MDD displays have no physical button, and they are used on a moving boat by people wearing sailing gloves, with spray on the glass. Every touch on the display is designed for the least precise finger in the worst conditions, and the full gesture vocabulary builds on these rules in the Patterns section.","sidebar":"designSidebar"},"foundations/typography":{"id":"foundations/typography","title":"Typography","description":"Two open-licence typefaces carry every MDD page. Noto Sans Black sets the large data values, and B612 Bold sets the dial numbers, labels and units. Every piece of text takes a named type role, which fixes its size and its typeface.","sidebar":"designSidebar"},"index":{"id":"index","title":"Display Design Guidelines","description":"These guidelines are the reference that every page, control and graphic asset on the SCADYS Marine Data Displays is designed against. They follow the shape of Apple\'s Human Interface Guidelines, cut down to a marine instrument that is read at a glance from across a cockpit by day and at night, and that is operated by a gloved, wet hand.","sidebar":"designSidebar"}}}}')}}]);